export function evaluateWatchTrigger(watch,state,{now=Date.now()}={}){if(!watch?.enabled)return {trigger:false,reason:'WATCH_DISABLED'};if(watch.startsAt&&now<Number(watch.startsAt))return {trigger:false,reason:'NOT_STARTED'};if(watch.endsAt&&now>Number(watch.endsAt))return {trigger:false,reason:'ENDED'};if(state.officialEmergency)return {trigger:true,reason:'OFFICIAL_EMERGENCY',safety:true};if(state.confidence!==undefined&&state.confidence<(watch.minConfidence??0))return {trigger:false,reason:'LOW_CONFIDENCE'};if(typeof watch.predicate!=='function')return {trigger:false,reason:'NO_PREDICATE'};return watch.predicate(state)?{trigger:true,reason:'PREDICATE_MATCH',safety:false}:{trigger:false,reason:'NO_MATCH'}}
